// Email helper
let _emailTransporter = null;
const getEmailTransporter = () => {
  if (_emailTransporter) return _emailTransporter;
  if (!process.env.GMAIL_USER || !process.env.GMAIL_PASS) return null;
  _emailTransporter = nodemailer.createTransport({
    service: 'gmail',
    auth: { user: process.env.GMAIL_USER, pass: process.env.GMAIL_PASS },
    pool: true,
    maxConnections: 5,
    rateLimit: true,
    rateDelta: 200
  });
  return _emailTransporter;
};
const sendEmail = async (to, subject, html) => {
  const transporter = getEmailTransporter();
  if (!transporter) return false;
  try {
    await transporter.sendMail({ from: process.env.GMAIL_USER, to, subject, html });
    return true;
  } catch (e) { console.warn('Email failed:', e.message); return false; }
};
const queueEmail = (tenantId, to, subject, body, isHtml = true) => pool.query('INSERT INTO email_queue(tenant_id,to_email,subject,body,html) VALUES($1,$2,$3,$4,$5)', [tenantId, to, subject, body, isHtml]).catch(e => console.error('[DB Error]', e.message));

// SMS helper
const sendSMS = async (phone, message) => {
  if (!process.env.AT_API_KEY || !process.env.AT_USERNAME) return false;
  // Check opt-outs before sending
  const optOut = await pool.query('SELECT 1 FROM sms_opt_outs WHERE phone=$1', [phone]);
  if (optOut.rows.length > 0) {
    console.log(`[SMS] Skipped opt-out number: ${phone}`);
    return { skipped: true, reason: 'opt_out' };
  }
  try {
    const africastalking = require('africastalking')({ apiKey: process.env.AT_API_KEY, username: process.env.AT_USERNAME });
    const response = await africastalking.SMS.send({ to: phone, message, from: process.env.AT_SENDER_ID || undefined });
    // Capture message ID from Africa's Talking for delivery receipt tracking
    const messageId = response?.SMSMessageData?.Recipients?.[0]?.id || null;
    return { sent: true, messageId };
  } catch (e) { console.warn('SMS failed:', e.message); return false; }
};
const logSMS = (tenantId, phone, message, triggerType, reference) => pool.query('INSERT INTO sms_logs(tenant_id,phone,message,trigger_type,reference) VALUES($1,$2,$3,$4,$5)', [tenantId, phone, message, triggerType || 'manual', reference || null]).catch(e => console.error('[DB Error]', e.message));

// Webhook delivery
const fireWebhook = async (tenantId, event, payload) => {
  const hooks = (await pool.query('SELECT * FROM webhooks WHERE tenant_id=$1 AND active=true AND $2=ANY(events)', [tenantId, event])).rows;
  for (const hook of hooks) {
    try {
      const sig = crypto.createHmac('sha256', hook.secret || '').update(JSON.stringify(payload)).digest('hex');
      const resp = await fetch(hook.url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Comfort-Sig': sig, 'X-Comfort-Event': event }, body: JSON.stringify(payload) });
      await pool.query('INSERT INTO webhook_logs(tenant_id,event,payload,status,response) VALUES($1,$2,$3,$4,$5)', [tenantId, event, JSON.stringify(payload), resp.status, '']);
    } catch (e) {
      await pool.query('INSERT INTO webhook_logs(tenant_id,event,payload,status,response) VALUES($1,$2,$3,$4,$5)', [tenantId, event, JSON.stringify(payload), 0, e.message]);
    }
  }
};

// Plan limits
const PLAN_LIMITS = { free: 50, basic: 500, pro: 50000, enterprise: Infinity };
const checkPlanLimit = async (tenantId, table, userRole) => {
  validateTable(table);
  if (userRole === 'super_admin') return { plan: 'enterprise', limit: Infinity, count: 0, allowed: true };
  const sub = (await pool.query('SELECT plan FROM subscriptions WHERE tenant_id=$1 AND status=$2 ORDER BY created_at DESC LIMIT 1', [tenantId, 'active'])).rows[0];
  const plan = sub?.plan || 'free';
  const limit = PLAN_LIMITS[plan] || 50;
  const count = (await pool.query(`SELECT COUNT(*) FROM ${table} WHERE tenant_id=$1`, [tenantId])).rows[0].count;
  return { plan, limit, count: parseInt(count), allowed: parseInt(count) < limit };
};
const requirePlanLimit = (table) => async (req, res, next) => {
  if (req.session.user?.role === 'super_admin') return next();
  const check = await checkPlanLimit(req.session.user.tenant_id, table);
  if (!check.allowed) return res.send(renderPage('Plan Limit', `<div class="card"><div class="alert alert-error"><h2>Plan Limit Reached</h2><p>You have ${check.count} records on the ${check.plan} plan (limit: ${check.limit}).</p><p>Upgrade to add more records.</p></div><a href="/billing" class="btn btn-gold">Upgrade Plan</a></div>`, req.session.user));
  next();
};

// ============================================================
// FEATURE GATING: Subscription-aware dashboard card rendering
// ============================================================
const PLAN_HIERARCHY = ['free', 'basic', 'pro', 'enterprise'];
const PLAN_NAMES = { free: 'Free', basic: 'Basic', pro: 'Professional', enterprise: 'Enterprise' };
const _planCache = new Map();
const PLAN_CACHE_TTL = 5 * 60 * 1000;

async function getTenantPlanInfo(tenantId) {
  const now = Date.now();
  const cached = _planCache.get(tenantId);
  if (cached && now - cached.ts < PLAN_CACHE_TTL) return cached;
  const sub = (await pool.query(
    "SELECT plan FROM subscriptions WHERE tenant_id=$1 AND status='active' ORDER BY created_at DESC LIMIT 1",
    [tenantId]
  )).rows[0];
  const plan = sub?.plan || 'free';
  const planIdx = PLAN_HIERARCHY.indexOf(plan);
  const flags = (await pool.query('SELECT feature_key, min_plan, is_active FROM feature_flags WHERE is_active = true')).rows;
  const accessible = new Set();
  for (const f of flags) {
    const minIdx = PLAN_HIERARCHY.indexOf(f.min_plan || 'free');
    if (planIdx >= minIdx) accessible.add(f.feature_key);
  }
  const info = { plan, planIdx, accessible, ts: now };
  _planCache.set(tenantId, info);
  return info;
}

async function hasFeature(tenantId, featureKey) {
  const info = await getTenantPlanInfo(tenantId);
  return info.accessible.has(featureKey);
}

// Render a dashboard card — locked or unlocked based on subscription
// featureKey: feature_flags.feature_key. null = always free/accessible.
// minPlanLabel: e.g. "Basic Plan" — shown on locked cards.
function featureCard({ title, desc, link, icon, btnClass, featureKey, planInfo, minPlanLabel }) {
  if (!featureKey || planInfo.accessible.has(featureKey)) {
    return `<div class="card"><h3>${icon ? icon + ' ' : ''}${title}</h3>${desc ? '<p>' + desc + '</p>' : ''}<a href="${link}" class="btn ${btnClass || 'btn-sm'}">${title}</a></div>`;
  }
  const lbl = minPlanLabel || PLAN_NAMES[featureKey] || featureKey;
  return `<div class="card" style="opacity:0.55;position:relative;overflow:hidden;border:1px dashed #f59e0b"><div style="position:absolute;top:8px;right:8px;background:#f59e0b;color:#fff;font-size:11px;padding:3px 10px;border-radius:6px;font-weight:700">&#128274; ${lbl}</div><h3>${icon ? icon + ' ' : ''}${title}</h3>${desc ? '<p>' + desc + '</p>' : '<p>Upgrade your plan to unlock this feature.</p>'}<a href="/billing" class="btn btn-sm btn-gold">Upgrade Plan</a></div>`;
}

// Permission check (v2.0)
const checkPermission = (perm) => async (req, res, next) => {
  const u = req.session.user;
  if (!u) return res.redirect('/login');
  if (u.role === 'super_admin') return next();
  try {
    const rp = (await pool.query('SELECT permissions FROM role_permissions WHERE tenant_id=$1 AND role_name=$2', [u.tenant_id, u.role])).rows[0];
    if (!rp) return next(); // No role defined = allow
    const perms = typeof rp.permissions === 'string' ? JSON.parse(rp.permissions) : rp.permissions;
    if (perms[perm] === true || perms.can_manage_users) return next();
    return res.status(403).send(renderPage('Access Denied', '<div class="card"><div class="alert alert-error">You do not have permission for this action.</div><a href="/dashboard" class="btn">Back to Dashboard</a></div>', req.session.user));
  } catch (e) { return next(); } // If check fails, allow
};

