// ============================================================
// v12.0: FLUTTERWAVE WEBHOOK + PAYMENT VERIFICATION
// ============================================================
// Flutterwave webhook handler (POST) - for server-to-server payment confirmation
app.post('/webhook/flutterwave', express.raw({ type: 'application/json' }), ah(async (req, res) => {
  const secret = process.env.FLW_WEBHOOK_SECRET || process.env.FLW_SECRET_KEY;
  const signature = req.headers['verif-hash'];
  if (!secret || !signature) {
    return res.status(401).send('Missing signature');
  }
  // Timing-safe comparison to prevent timing attacks
  try {
    const sigBuf = Buffer.from(signature, 'utf8');
    const secretBuf = Buffer.from(secret, 'utf8');
    if (sigBuf.length !== secretBuf.length || !crypto.timingSafeEqual(sigBuf, secretBuf)) {
      return res.status(401).send('Invalid signature');
    }
  } catch (e) {
    return res.status(401).send('Invalid signature');
  }
  let payload;
  try { payload = JSON.parse(req.body.toString()); } catch { return res.status(400).send('Invalid JSON'); }
  
  if (payload.event === 'charge.completed' && payload.data?.status === 'successful') {
    const { tx_ref, amount, currency, id: flw_id, customer } = payload.data;
    // Use transaction to prevent race condition (double-crediting)
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const payment = (await client.query('SELECT * FROM payments WHERE reference=$1 AND status=$2 FOR UPDATE', [tx_ref, 'pending'])).rows[0];
      if (payment) {
        await client.query('UPDATE payments SET status=$1, method=$2 WHERE reference=$3', ['completed', 'flutterwave', tx_ref]);
        const plan = payment.plan || (payment.description?.includes('enterprise') ? 'enterprise' : payment.description?.includes('pro') ? 'pro' : 'basic');
        const expires = new Date(Date.now() + SUBSCRIPTION_DURATION);
        try { await client.query('INSERT INTO subscriptions(tenant_id,plan,amount,status,expires_at,payment_method,reference) VALUES($1,$2,$3,$4,$5,$6,$7)', [payment.tenant_id, plan, payment.amount, 'active', expires, 'flutterwave', tx_ref]); } catch(e) { console.error('[Error]', e.message); }
        await client.query('UPDATE tenants SET verified=true,approved=true WHERE id=$1', [payment.tenant_id]);
        const devShare = Math.round(payment.amount * 0.9);
        try { await client.query('INSERT INTO developer_revenue(tenant_id,source,amount,description) VALUES($1,$2,$3,$4)', [payment.tenant_id, 'subscription', devShare, `${plan} plan via Flutterwave`]); } catch(e) { console.error('[Error]', e.message); }
        await client.query('COMMIT');
        await fireWebhook(payment.tenant_id, 'payment', { ref: tx_ref, amount: payment.amount, plan, flw_id });
        await evaluateAutomations(payment.tenant_id, 'fee.paid', { amount: payment.amount, plan });
        await audit(payment.tenant_id ? 'system' : 'unknown', 'payment_completed', `Flutterwave: ${tx_ref} UGX ${amount}`);
        console.log(`[Flutterwave] Payment confirmed: ${tx_ref} - UGX ${amount}`);
      } else {
        await client.query('COMMIT');
      }
    } catch (e) {
      await client.query('ROLLBACK');
      console.error('[Flutterwave] Payment processing error:', e.message);
    } finally {
      client.release();
    }
    // Also check MoMo payments
    const momo = (await pool.query('SELECT * FROM momo_payments WHERE external_ref=$1 AND status!=$2', [tx_ref, 'completed'])).rows[0];
    if (momo) {
      await pool.query('UPDATE momo_payments SET status=$1 WHERE external_ref=$2', ['completed', tx_ref]);
      await pool.query('INSERT INTO payments(tenant_id,amount,method,status,description,reference) VALUES($1,$2,$3,$4,$5,$6)', [momo.tenant_id, momo.amount, 'mobile_money', 'completed', momo.reference, tx_ref]);
    }
  }
  res.status(200).send('OK');
}));

// SMS delivery receipt webhook (Africa's Talking callback)
app.post('/webhook/sms/delivery', express.json(), ah(async (req, res) => {
  const { status, phoneNumber, id, retryCount } = req.body;
  console.log(`[SMS Delivery] Received: status=${status} phone=${phoneNumber} ref=${id} retries=${retryCount}`);
  try {
    await pool.query("UPDATE sms_logs SET status=$1 WHERE reference=$2", [status, id]);
    console.log(`[SMS Delivery] Updated ${status} for ${phoneNumber} (ref: ${id})`);
  } catch (e) { console.warn('[SMS Delivery] Error:', e.message); }
  res.sendStatus(200);
}));

// Flutterwave payment verification endpoint
app.get('/api/v1/payment/verify/:ref', ah(async (req, res) => {
  const ref = req.params.ref;
  if (!process.env.FLW_SECRET_KEY) return res.json({ verified: false, error: 'No Flutterwave key' });
  try {
    const resp = await fetch(`https://api.flutterwave.com/v3/transactions/${ref}/verify`, {
      headers: { 'Authorization': `Bearer ${process.env.FLW_SECRET_KEY}` }
    });
    const data = await resp.json();
    if (data.status === 'success' && data.data?.status === 'successful') {
      return res.json({ verified: true, amount: data.data.amount, currency: data.data.currency, ref: data.data.tx_ref });
    }
    return res.json({ verified: false, status: data.data?.status });
  } catch (e) { return res.json({ verified: false, error: e.message }); }
}));

