// ============================================================
// FEATURE 0: UNIVERSAL DEV ACCESS (Portal Switcher)
// ============================================================
const DEV_PORTAL_TYPES = [
  { type: 'school', label: 'School Portal', icon: '🏫', color: '#3b82f6' },
  { type: 'church', label: 'Church Portal', icon: '⛪', color: '#8b5cf6' },
  { type: 'business', label: 'Business Portal', icon: '🏢', color: '#f59e0b' },
  { type: 'organization', label: 'Organization Portal', icon: '🤝', color: '#10b981' },
  { type: 'individual', label: 'Individual Portal', icon: '👤', color: '#ec4899' },
  { type: 'health', label: 'Health Portal', icon: '🏥', color: '#ef4444' },
  { type: 'public', label: 'Public Portal', icon: '🌐', color: '#0ea5e9' }
];

app.get('/dev/portals', requireAuth, requireSuperAdmin, ah(async (req, res) => {
  const original = req.session._original_tenant;
  const current = req.session.user;
  const devEmail = current.email;
  // AUTO-CREATE all missing demo tenants
  for (const p of DEV_PORTAL_TYPES) {
    const tenantName = p.type === 'public' ? 'Dev Public Portal' : 'Dev ' + p.type.charAt(0).toUpperCase() + p.type.slice(1) + 'Portal';
    const tenantType = p.type === 'public' ? 'public' : p.type;
    const exists = (await pool.query(`SELECT id FROM tenants WHERE email=$1 AND name=$2`, [devEmail, tenantName])).rows[0];
    if (!exists) {
      const devSubdomain = 'dev-' + tenantType + '-' + Math.floor(Math.random() * 9999);
      const created = (await pool.query(`INSERT INTO tenants (name, type, email, verified, approved, subdomain, has_fundraising) VALUES ($1,$2,$3,true,true,$4,true) RETURNING id`, [tenantName, tenantType, devEmail, devSubdomain])).rows[0];
      await pool.query(`INSERT INTO subscriptions (tenant_id, plan, status) VALUES ($1,'enterprise','active') ON CONFLICT DO NOTHING`, [created.id]);
      audit(devEmail, 'dev_auto_create', 'Auto-created tenant: ' + tenantName + ' (#' + created.id + ')');
    }
  }
  const existing = (await pool.query(
    `SELECT id, name, type FROM tenants WHERE email = $1 AND name ILIKE 'Dev %'`,
    [devEmail]
  )).rows;
  const existingMap = {};
  existing.forEach(r => { existingMap[r.type] = r; });
  const cards = DEV_PORTAL_TYPES.map(p => {
    const demo = existingMap[p.type];
    const isActive = current.tenant_type === p.type && (original || current.tenant_name && current.tenant_name.startsWith('Dev'));
    const csrfVal = req.csrfToken || req.session?.csrfToken || '';
    return `<form method="POST" action="/dev/switch-tenant" style="border:2px solid ${isActive ? '#22c55e' : '#e2e8f0'};border-radius:12px;padding:20px;text-align:center;cursor:pointer;background:${isActive ? '#f0fdf4' : '#fff'};margin:0;display:block;transition:all 0.2s" onclick="if(!${isActive})this.submit()" onmouseover="this.style.transform='translateY(-3px)';this.style.boxShadow='0 6px 20px rgba(0,0,0,0.1)'" onmouseout="this.style.transform='';this.style.boxShadow=''">
      <input type="hidden" name="_csrf" value="${esc(csrfVal)}">
      <input type="hidden" name="type" value="${esc(p.type)}">
      <div style="font-size:48px;margin-bottom:8px;pointer-events:none">${p.icon}</div>
      <h3 style="margin:0 0 4px;pointer-events:none">${esc(p.label)}</h3>
      <p style="font-size:13px;color:#64748b;margin:0 0 12px;pointer-events:none">${demo ? 'Tenant #' + demo.id + ' exists' : 'Not yet created'}</p>
      ${isActive ? '<span style="color:#22c55e;font-weight:bold;font-size:13px;pointer-events:none">&#9679; ACTIVE</span>' : '<button type="submit" class="btn" style="background:' + p.color + ';color:#fff;font-size:13px">Switch to ' + esc(p.type) + '</button>'}
    </form>`;
  }).join('');
  res.send(renderPage('Dev Portal Switcher', `
    <div class="hero" style="background:linear-gradient(135deg,#6366f1,#8b5cf6);padding:24px;border-radius:16px;margin-bottom:20px;color:white">
      <h1>Dev Portal Switcher</h1>
      <p style="opacity:0.9;margin-top:4px">Click any portal to create a demo tenant and switch your session</p>
      ${original ? '<p style="background:rgba(255,255,255,0.2);display:inline-block;padding:6px 14px;border-radius:8px;margin-top:8px">Original: ' + esc(original.name) + ' (' + esc(original.type) + ')</p>' : ''}
    </div>
    ${original ? '<div style="margin-bottom:16px"><a href="/dev/restore-session" class="btn btn-gold">&larr; Restore Original Session (' + esc(original.name) + ')</a></div>' : ''}
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px">${cards}</div>
  `, req.session.user));
}));

app.post('/dev/switch-tenant', requireAuth, requireSuperAdmin, ah(async (req, res) => {
  // Handle both string and array _csrf values (from duplicate inputs)
  const rawType = Array.isArray(req.body.type) ? req.body.type[0] : req.body.type;
  const type = String(rawType || '').trim().toLowerCase();
  if (!DEV_PORTAL_TYPES.find(p => p.type === type)) {
    console.warn('[Portal Switch] Invalid type:', rawType, 'body:', JSON.stringify(req.body).substring(0, 200));
    return res.status(400).send('Invalid portal type: ' + esc(type));
  }
  const user = req.session.user;
  if (!req.session._original_tenant) {
    req.session._original_tenant = { id: user.tenant_id, name: user.tenant_name, type: user.tenant_type };
  }
  const tenantName = type === 'public' ? 'Dev Public Portal' : 'Dev ' + type.charAt(0).toUpperCase() + type.slice(1) + 'Portal';
  const tenantType = type === 'public' ? 'public' : type;
  let tenant = (await pool.query(
    `SELECT id, name, type FROM tenants WHERE email = $1 AND name = $2`,
    [user.email, tenantName]
  )).rows[0];
  if (!tenant) {
    const portalSubdomain = 'portal-' + tenantType + '-' + Math.floor(Math.random() * 9999);
    tenant = (await pool.query(
      `INSERT INTO tenants (name, type, email, verified, approved, subdomain, has_fundraising) VALUES ($1, $2, $3, true, true, $4, true) RETURNING id, name, type`,
      [tenantName, tenantType, user.email, portalSubdomain]
    )).rows[0];
    await pool.query(`INSERT INTO subscriptions (tenant_id, plan, status) VALUES ($1, 'enterprise', 'active')`, [tenant.id]);
    audit(user.email, 'dev_create_tenant', 'Created demo tenant: ' + tenantName + ' (#' + tenant.id + ')');
  } else {
    // Ensure fundraising is enabled for any existing dev tenant
    await pool.query(`UPDATE tenants SET has_fundraising = true WHERE id = $1 AND has_fundraising = false`, [tenant.id]);
  }
  await pool.query(`UPDATE users SET tenant_id = $1 WHERE email = $2`, [tenant.id, user.email]);
  req.session.user.tenant_id = tenant.id;
  req.session.user.tenant_name = tenant.name;
  req.session.user.tenant_type = type;
  req.session._impersonate_tenant_id = tenant.id;
  audit(user.email, 'dev_switch_tenant', 'Switched to ' + tenantName + ' (#' + tenant.id + ')');
  res.redirect('/portal/' + type);
}));

app.get('/dev/restore-session', requireAuth, requireSuperAdmin, ah(async (req, res) => {
  const orig = req.session._original_tenant;
  if (!orig) return res.redirect('/dev/portals');
  const user = req.session.user;
  await pool.query(`UPDATE users SET tenant_id = $1 WHERE email = $2`, [orig.id, user.email]);
  req.session.user.tenant_id = orig.id;
  req.session.user.tenant_name = orig.name;
  req.session.user.tenant_type = orig.type;
  delete req.session._original_tenant;
  audit(user.email, 'dev_restore_session', 'Restored to ' + orig.name + ' (#' + orig.id + ')');
  res.redirect('/dashboard');
}));

