// Scheduled reports runner (every minute)
setInterval(async () => {
  try {
    const due = (await pool.query(`SELECT * FROM scheduled_reports WHERE is_active=true AND next_run <= NOW()`)).rows;
    for (const sr of due) {
      try {
        const emailList = (sr.recipients || '').split(',').map(e => e.trim()).filter(Boolean);
        const subject = 'Scheduled Report: ' + sr.name + ' (' + sr.report_type + ')';
        const body = '<p>This is your scheduled <strong>' + esc(sr.report_type) + '</strong> report for <strong>' + esc(sr.name) + '</strong>.</p><p>Generated at: ' + new Date().toISOString() + '</p>';
        for (const email of emailList) { await queueEmail(sr.tenant_id, email, subject, body); }
        const freq = sr.frequency;
        const interval = freq === 'daily' ? '{1 day}' : freq === 'weekly' ? '{7 days}' : freq === 'monthly' ? '{1 month}' : '{3 months}';
        await pool.query(`UPDATE scheduled_reports SET last_run=NOW(), next_run=NOW() + interval '${interval}' WHERE id=$1`, [sr.id]);
        await pool.query(`INSERT INTO report_history (tenant_id,scheduled_report_id,report_type,recipients,status) VALUES ($1,$2,$3,$4,'sent')`, [sr.tenant_id, sr.id, sr.report_type, sr.recipients]);
        console.log('[ScheduledReport] Ran: ' + sr.name + ' (ID:' + sr.id + ')');
      } catch (err) {
        await pool.query(`INSERT INTO report_history (tenant_id,scheduled_report_id,report_type,recipients,status,error_message) VALUES ($1,$2,$3,$4,'failed',$5)`, [sr.tenant_id, sr.id, sr.report_type, sr.recipients, err.message]);
      }
    }
  } catch (e) { /* scheduler error */ }
}, 60000);

